// Supplemental spell clips: Generic JB2A assets mapped onto built-ins that have no
// dedicated Library/<Spell>/ folder. Local reuses point at already-bundled files;
// entries with `source` are downloaded by scripts/bundle-remaining-spell-fx.mjs.
// BLFX-dedicated clips (blfx-*) are catalogue assets copied into /assets/animations.
export const animationSourceRevision = 'e930132102cbfa22a0ba964a3df73feb3412727a';
const gh = (path) => `https://raw.githubusercontent.com/Jules-Bens-Aa/JB2A_DnD5e/${animationSourceRevision}/${path}`;

function clip(id, label, spells, {kind = 'burst', anchor, length, diameter = 2, source, url, duration = 1450} = {}) {
  return {
    id, label, spells, kind,
    anchor: anchor ?? (kind === 'cone' ? 'caster' : 'target'),
    url: url ?? `/assets/animations/${id}.webm`,
    scale: 1, duration, diameter, length,
    ...(source ? {source} : {}),
  };
}

